expression:
local({
  wd <- coalesce(
    if_else(as.numeric(tv_wd_hours) %in% 0:6, as.numeric(tv_wd_hours), NA_real_),
    recode_values(as.numeric(tv_wd_band), 1 ~ 0, 2 ~ 0.5, 3 ~ 1.5, 4 ~ 2.5, 5 ~ 4, 6 ~ 5)
  )
  we <- coalesce(
    if_else(as.numeric(tv_we_hours) %in% 0:6, as.numeric(tv_we_hours), NA_real_),
    recode_values(as.numeric(tv_we_band), 1 ~ 0, 2 ~ 0.5, 3 ~ 1.5, 4 ~ 2.5, 5 ~ 4, 6 ~ 5)
  )
  (5 * wd + 2 * we) / 7
})

local({
  wd <- coalesce(
    if_else(as.numeric(game_wd_hours) %in% 0:6, as.numeric(game_wd_hours), NA_real_),
    recode_values(as.numeric(game_wd_band), 1 ~ 0, 2 ~ 0.5, 3 ~ 1.5, 4 ~ 2.5, 5 ~ 4, 6 ~ 5)
  )
  we <- coalesce(
    if_else(as.numeric(game_we_hours) %in% 0:6, as.numeric(game_we_hours), NA_real_),
    recode_values(as.numeric(game_we_band), 1 ~ 0, 2 ~ 0.5, 3 ~ 1.5, 4 ~ 2.5, 5 ~ 4, 6 ~ 5)
  )
  (5 * wd + 2 * we) / 7
})
